double uniform_random(unsigned int& seed, unsigned int a, unsigned int c, unsigned int m) {
    seed = (a * seed + c) % m;
    return (static_cast<double>(seed) / m);
}

double exponential_random(double lambda, unsigned int& seed, unsigned int a, unsigned int c, unsigned int m) {
    double u = uniform_random(seed, a, c, m);
    while (u == 1.0) {
        u = uniform_random(seed, a, c, m);
    }
    return -std::log(1.0 - u) / lambda;
}
```
